#!/usr/bin/env bash
# THE source of truth for what each unit bench is built from.
#
# GENERATED by tools/gen_bench_sources.py -- do not edit by hand; change the
# table there and re-run it. The gate runs `gen_bench_sources.py --check`, so
# a hand edit or a stale table fails the suite rather than silently building
# a different design.
#
# Consumers: tests/pc9821/run.sh (the gate) and tools/bench.py (one bench,
# or --all). They must not disagree about the file list.

